CREATE TABLE spike.events UUID 'd33a4032-a9c6-4644-9792-21e7d60034ff' (`id` UInt64, `ts` DateTime DEFAULT now(), `user_id` UInt32 CODEC(Delta(4), ZSTD(3)), `payload` String DEFAULT '' CODEC(ZSTD(1)), `amount` Float64 DEFAULT 0, `note` String DEFAULT '', INDEX idx_user user_id TYPE minmax GRANULARITY 4) ENGINE = MergeTree PARTITION BY toYYYYMM(ts) ORDER BY id TTL ts + toIntervalYear(5) SETTINGS index_granularity = 8192